                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      const roy = cost == null ? null : Math.max(0, Math.round((p * rate - cost) * 100) / 100);
